/* VoltCalc Guiado — demonstração acadêmica baseada somente nas tabelas
 * 31, 32, 35 e 37 (item 1) da NBR 5410:1997 fornecida.
 * NÃO certifica conformidade ou segurança de uma instalação.
 */
(()=>{
'use strict';
const DB=window.NBR1997;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>Number.isFinite(Number(v))&&v!==null&&v!==''?Number(v).toLocaleString('pt-BR',{maximumFractionDigits:d}):'—';
const num=x=>x===''||x===null||x===undefined?NaN:Number(x);
const id=()=>('c'+Date.now().toString(36)+Math.random().toString(36).slice(2,8));
const STORAGE='voltcalc_guiado_v2';
const types=[['lighting','Iluminação','Lâmpadas e luminárias','☼'],['sockets','Tomadas','Uso geral ou específico','♧'],['motor','Motor elétrico','Bomba, ventilador, máquinas','⚙'],['shower','Chuveiro','Aquecimento elétrico','♨'],['transformer','Transformador','Alimentação de outros circuitos','▣'],['other','Outro equipamento','Qualquer carga elétrica','⌁']];
const installations=[
 {id:'embedded',name:'Em eletroduto embutido',desc:'Tubulação dentro da parede',method:'B1 / B2',kind:'embedded'},
 {id:'conduit',name:'Em eletroduto aparente',desc:'Tubulação visível sobre a parede',method:'B1 / B2',kind:'conduit'},
 {id:'surface',name:'Sobre a parede',desc:'Cabo fixado diretamente',method:'C',kind:'surface'},
 {id:'buried',name:'Enterrado no solo',desc:'Cabo protegido em eletroduto',method:'D',kind:'buried'},
 {id:'tray',name:'Em bandeja ou leito',desc:'Cabos sobre suporte aberto',method:'E / F / G',kind:'tray'},
 {id:'overhead',name:'Ao ar livre',desc:'Cabos externos sem eletroduto',method:'A definir',kind:'overhead'}
];
const LABELS=['Tipo de circuito','Potência e tensão','Instalação do cabo','Cabos juntos ou separados','Temperatura e distância','Resultado'];
const newCircuit=()=>({id:id(),description:'TR-01',type:'transformer',quantity:1,power:30,unit:'kVA',phase:'tri',voltage:380,powerFactor:1,efficiency:.9,installation:'embedded',wall:'masonry',cableForm:'single',methodOverride:'',insulation:'XLPE',metal:'Cu',loaded:3,groupCount:1,groupLayout:'bundle',temperature:35,length:50,maxDrop:3,breakerCurve:'C',i2Factor:1.45,breakerIcu:'',shortIk:'',soilResistance:'',soilDepth:'',unknownInstallation:false});
let state={projectName:'Residência Exemplo',circuits:[],draft:newCircuit(),editingId:null,selected:null,step:1,mode:'guided',page:'wizard',reactance:.08};
let tableShown='31';
function load(){try{const stored=JSON.parse(localStorage.getItem(STORAGE)||'null');if(stored&&Array.isArray(stored.circuits)){state={...state,projectName:String(stored.projectName||'Projeto').slice(0,60),circuits:stored.circuits.slice(0,300).map(clean),draft:clean(stored.draft||newCircuit()),selected:stored.selected,editingId:stored.circuits.some(c=>c.id===stored.editingId)?stored.editingId:null,reactance:Number.isFinite(+stored.reactance)&&+stored.reactance>=0&&+stored.reactance<=2?+stored.reactance:.08};}}catch(e){console.warn(e);} }
function clean(data){const def=newCircuit(),keys=Object.keys(def),out={...def};for(const k of keys)if(Object.prototype.hasOwnProperty.call(data||{},k))out[k]=data[k];out.id=typeof out.id==='string'&&out.id.length<64?out.id:id();out.description=String(out.description).slice(0,70);if(!types.some(t=>t[0]===out.type))out.type='other';if(!installations.some(t=>t.id===out.installation))out.installation='embedded';if(!['mono','tri'].includes(out.phase))out.phase='tri';if(!['PVC','XLPE','EPR'].includes(out.insulation))out.insulation='XLPE';if(!['Cu','Al'].includes(out.metal))out.metal='Cu';if(!['single','multi'].includes(out.cableForm))out.cableForm='single';if(!['masonry','thermal'].includes(out.wall))out.wall='masonry';if(!['bundle','spaced','unknown'].includes(out.groupLayout))out.groupLayout='unknown';if(!['A1','A2','B1','B2','C','D',''].includes(out.methodOverride))out.methodOverride='';if(!['W','kW','VA','kVA','CV','HP'].includes(out.unit))out.unit='W';if(!['B','C','D'].includes(out.breakerCurve))out.breakerCurve='C';return out;}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({projectName:state.projectName,circuits:state.circuits,draft:state.draft,selected:state.selected,editingId:state.editingId,reactance:state.reactance}));return true;}catch{toast('Não foi possível salvar neste navegador. Exporte um backup JSON.');return false;}}
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function methodOf(c){if(c.unknownInstallation)return null;if(c.methodOverride)return c.methodOverride;switch(c.installation){case 'embedded':return c.wall==='thermal'?(c.cableForm==='single'?'A1':'A2'):(c.cableForm==='single'?'B1':'B2');case 'conduit':return c.cableForm==='single'?'B1':'B2';case 'surface':return 'C';case 'buried':return 'D';default:return null;}}

// Toda a matemática e seleção de componentes são executadas no servidor Python.
const resultCache=new Map(),pendingCalculations=new Map();
let serviceError='',renderVersion=0,summaryVersion=0;
const resultKey=c=>JSON.stringify([c,state.reactance]);
const viewKey=()=>JSON.stringify([state.draft,state.circuits,state.reactance,state.page,state.step,state.mode]);
async function prepareResults(circuits){
 const missing=circuits.filter((c,i,items)=>!resultCache.has(resultKey(c))&&!pendingCalculations.has(resultKey(c))&&items.findIndex(x=>resultKey(x)===resultKey(c))===i);
 if(missing.length){
  const snapshots=missing.map(c=>JSON.parse(JSON.stringify(c))),reactance=state.reactance,keys=snapshots.map(c=>JSON.stringify([c,reactance]));
  const task=(async()=>{
   try{
    const response=await fetch('/api/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({circuits:snapshots,reactance}),signal:AbortSignal.timeout(15000)});
    const data=await response.json();
    if(!response.ok||!Array.isArray(data.results)||data.results.length!==keys.length)throw Error(data.error||'Resposta inválida do servidor.');
    data.results.forEach((result,i)=>resultCache.set(keys[i],result));
    serviceError='';
    while(resultCache.size>1000)resultCache.delete(resultCache.keys().next().value);
   }catch(error){serviceError='Não foi possível calcular. Confira se o servidor Python está aberto e tente novamente.';}
   finally{keys.forEach(key=>pendingCalculations.delete(key));}
  })();
  keys.forEach(key=>pendingCalculations.set(key,task));
 }
 await Promise.all(circuits.map(c=>pendingCalculations.get(resultKey(c))).filter(Boolean));
 return circuits.every(c=>resultCache.has(resultKey(c)));
}
function calculate(c){
 const cached=resultCache.get(resultKey(c));
 if(cached)return {...cached,c};
 return {c,method:methodOf(c),ib:null,fct:null,fca:null,eligible:false,all:[],smallest:null,chosen:null,shortOk:null,issues:[serviceError||'Calculando…'],notices:[],table:c.insulation==='PVC'?31:32};
}
function markIssue(c,step){if(step===1)return !String(c.description||'').trim()||!(+c.quantity>=1&&Number.isInteger(+c.quantity));if(step===2)return !(+c.power>0&&+c.voltage>0&&+c.powerFactor>0&&+c.powerFactor<=1)||(['CV','HP'].includes(c.unit)&&!(+c.efficiency>0&&+c.efficiency<=1));if(step===3)return !c.installation; if(step===4)return !(+c.groupCount>=1&&+c.groupCount<=20);if(step===5)return !(+c.length>=0&&+c.maxDrop>0)||!(+c.temperature>=-30);return false;}
function checkStep(c,step){if(markIssue(c,step)){toast('Confira os campos obrigatórios antes de prosseguir.');return false;}return true;}
function field(label,key,opts={}){const c=state.draft,tip=opts.tip?` <button type="button" class="help-btn" data-help="${esc(key)}" title="Ver explicação">?</button>`:'';let ctl;if(opts.options)ctl=`<select data-field="${key}">${opts.options.map(([val,txt])=>`<option value="${esc(val)}" ${String(c[key])===String(val)?'selected':''}>${esc(txt)}</option>`).join('')}</select>`;else ctl=`<input data-field="${key}" ${opts.type==='text'?'type="text"':'type="number"'} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.step!==undefined?`step="${opts.step}"`:''} value="${esc(c[key])}" placeholder="${esc(opts.placeholder||'')}">`;
return `<div class="field"><label>${label}${tip}</label>${ctl}${opts.hint?`<span class="hint">${opts.hint}</span>`:''}</div>`;}
function selectCards(data,value,key,withArtwork=false){return `<div class="${withArtwork?'picture-grid':'choice-grid'}">${data.map(item=>{let obj=withArtwork?item:{id:item[0],name:item[1],desc:item[2],emoji:item[3]};const active=obj.id===value;return `<button type="button" role="radio" aria-checked="${active}" class="${withArtwork?'picture-card':'choice-btn'} ${active?'selected':''}" data-choose="${key}" data-value="${esc(obj.id)}">${withArtwork?`<span class="radio-mark"></span>${installationArt(obj.kind)}<strong>${esc(obj.name)}</strong><small>${esc(obj.desc)}</small><span class="method-chip">Referência: ${esc(obj.method)}</span>`:`<span class="choice-icon">${obj.emoji}</span><strong>${esc(obj.name)}</strong><small>${esc(obj.desc)}</small>`}</button>`;}).join('')}</div>`;}
function installationArt(kind){let bg='',content='';let defs=`<defs><linearGradient id="wall" x1="0" x2="1"><stop stop-color="#e5e8eb"/><stop offset="1" stop-color="#cbd3da"/></linearGradient><linearGradient id="tube" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#b0c5d2"/><stop offset=".43" stop-color="#f6fbff"/><stop offset="1" stop-color="#809aa8"/></linearGradient><linearGradient id="earth" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#bc8759"/><stop offset="1" stop-color="#7e543c"/></linearGradient></defs>`;
const wires=(x1,y1,x2,y2)=>[['#252c36',-10],['#1b6cc8',-3],['#2c9653',4],['#c29118',11]].map(([color,dy])=>`<path d="M${x1} ${y1+dy} L${x2} ${y2+dy}" stroke="${color}" stroke-width="7" fill="none" stroke-linecap="round"/>`).join('');
if(kind==='embedded'){bg=`<rect width="300" height="130" fill="#e7ecf0"/><rect x="8" y="0" width="105" height="130" fill="url(#wall)"/><path d="M110 0v130" stroke="#a0adb9" stroke-width="5"/><rect x="80" y="10" width="65" height="104" rx="4" fill="#adbbc7"/>`;content=`<path d="M125 13 V64 Q125 88 152 88 H280" fill="none" stroke="#6f8590" stroke-width="42"/><path d="M125 13 V64 Q125 88 152 88 H280" fill="none" stroke="url(#tube)" stroke-width="34"/>${[['#263242',-9],['#286ebd',-3],['#d5b438',3],['#329553',9]].map(([co,dy])=>`<path d="M125 15V64Q125 ${78+dy} 151 ${78+dy}H278" stroke="${co}" stroke-width="5" fill="none"/>`).join('')}`;}
else if(kind==='conduit'){bg=`<rect width="300" height="130" fill="#ebeff2"/><path d="M0 102H300" stroke="#d8e1e7" stroke-width="2"/>`;content=`<rect x="22" y="41" width="260" height="50" rx="25" fill="#a1b1c1"/><rect x="22" y="46" width="258" height="40" rx="20" fill="url(#tube)"/><rect x="50" y="35" width="14" height="61" rx="3" fill="#8298a5"/><rect x="221" y="35" width="14" height="61" rx="3" fill="#8298a5"/><circle cx="57" cy="44" r="2" fill="#fff"/><circle cx="228" cy="44" r="2" fill="#fff"/>${wires(231,70,293,70)}`;}
else if(kind==='surface'){bg=`<rect width="300" height="130" fill="#eceff2"/>`;content=`${wires(5,65,295,65)}<rect x="65" y="39" width="11" height="55" rx="4" fill="#788fa3" opacity=".9"/><rect x="208" y="39" width="11" height="55" rx="4" fill="#788fa3" opacity=".9"/><circle cx="71" cy="49" r="2.3" fill="#dbe6ef"/><circle cx="214" cy="49" r="2.3" fill="#dbe6ef"/>`;}
else if(kind==='buried'){bg=`<rect width="300" height="130" fill="url(#earth)"/><path d="M0 27 Q75 33 150 27 T300 27" stroke="#77a446" stroke-width="18" fill="none"/><path d="M0 40H300" stroke="#d5a275" stroke-width="3" stroke-dasharray="15 7"/><path d="M0 108H300" stroke="#75533e" stroke-width="3" stroke-dasharray="12 8"/>`;content=`<rect x="16" y="65" width="268" height="40" rx="19" fill="#424a50"/><rect x="21" y="72" width="260" height="27" rx="14" fill="#242c32"/>${wires(30,85,272,85)}`;}
else if(kind==='tray'){bg=`<rect width="300" height="130" fill="#e7eef4"/>`;content=`<path d="M10 45L85 97H284L213 45Z" fill="#a2b4c1" stroke="#708aa0" stroke-width="4"/><path d="M10 48L85 100M51 48L125 100M90 48L160 100M135 48L203 100M175 48L244 100" stroke="#e5f2ff" stroke-width="6"/><path d="M85 100L85 117M284 100v17" stroke="#6f8a99" stroke-width="8"/>${[['#1d2a37',10],['#2771bd',18],['#259754',26],['#d3a423',34]].map(([co,y])=>`<path d="M24 ${y+39}L96 ${y+44}H270" fill="none" stroke="${co}" stroke-width="7" stroke-linecap="round"/>`).join('')}`;}
else {bg=`<rect width="300" height="130" fill="#a9d7fa"/><circle cx="244" cy="24" r="14" fill="#ffe5a0"/><path d="M0 100Q80 80 140 106T300 103V130H0" fill="#86b782"/>`;content=`<path d="M120 12v117" stroke="#725d4e" stroke-width="13"/><path d="M103 42h81" stroke="#715d4d" stroke-width="9"/><path d="M0 51Q65 70 120 50T300 48M0 65Q68 83 120 64T300 63" fill="none" stroke="#202936" stroke-width="4"/><path d="M120 47v-10M178 48v-10" stroke="#e8edf7" stroke-width="5"/>`;}
return `<svg class="picture-art" viewBox="0 0 300 130" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Ilustração técnica simplificada da instalação">${defs}${bg}${content}</svg>`;}
const helps={power:'Use a potência nominal da placa do equipamento. Diferencie potência elétrica de entrada (W/kW) e potência mecânica do eixo (CV/HP).',unit:'kVA e VA já representam potência aparente. Para W e kW em corrente alternada também é necessário o fator de potência.',powerFactor:'É o cos φ da carga. Para transformadores em kVA, o valor não altera a corrente obtida da potência aparente. Não presuma 1,00 para cargas desconhecidas.',efficiency:'Para CV ou HP, informe o rendimento real do motor conforme placa ou documentação.',voltage:'Em alimentação trifásica use tensão entre fases (por exemplo 380 V). Em monofásica use a tensão aplicada à carga.',installation:'A aparência do cabo não determina sozinha o método da tabela 28. O tipo de cabo, o material da parede e o percurso também importam.',cableForm:'Condutores isolados ou cabos unipolares não são equivalentes a cabos multipolares. Isso altera as colunas A1/A2 e B1/B2.',groupCount:'Conte os circuitos que compartilham as condições de agrupamento. Não é o número de fios do mesmo circuito nem o número de equipamentos.',temperature:'Considere a temperatura real no local dos cabos. Tabela 35: referência 30 °C no ar e 20 °C no solo (edição 1997).',length:'Informe a distância de ida entre origem e carga. A fórmula usada pelo aplicativo já considera ida e retorno no monofásico.',loaded:'Número de condutores efetivamente carregados para consulta da tabela de corrente. Não conte automaticamente o PE; o neutro pode exigir análise específica.',insulation:'PVC é considerado com 70 °C de temperatura máxima em serviço contínuo; EPR e XLPE com 90 °C nas condições aplicáveis.',maxDrop:'É o limite de queda de tensão adotado no projeto. O valor admissível depende da origem e condições da instalação; não existe um percentual único para todos os casos.',i2Factor:'Relação entre a corrente convencional de atuação I₂ do dispositivo e sua corrente nominal In. Deve ser obtida das características reais do produto.',shortIk:'Corrente de curto-circuito presumida no ponto da instalação; precisa ser calculada ou conhecida.',breakerIcu:'Capacidade de interrupção declarada do disjuntor para a tensão e as condições reais. A comparação Ik ≤ Icu isolada não encerra a proteção.',soilResistance:'Resistividade térmica do solo é um parâmetro que altera a dissipação de calor do cabo enterrado. O MVP não aplica correção arbitrária para solo diferente da referência.',soilDepth:'A profundidade e a forma de enterramento modificam as condições térmicas. Precisam ser verificadas.'};
function intro(step){return `<span class="eyebrow">Passo ${step} de 6</span><h2>${['','O que você vai alimentar?','Qual é a potência do equipamento?','Como o cabo será instalado?','Os cabos ficarão juntos?','Quais são as condições do local?','Resultado do dimensionamento'][step]} <button class="help-btn" data-help="${step===3?'installation':step===4?'groupCount':step===5?'temperature':'power'}">?</button></h2><p class="step-description">${['','Escolha a utilização principal do circuito. Isso ajuda a orientar as próximas informações.','Use os dados da placa do equipamento ou do projeto elétrico.','Escolha o desenho mais parecido com sua instalação. Quando precisar, complemente os detalhes logo abaixo.','Informe quantos circuitos compartilham o caminho e como eles estão dispostos.','A temperatura, distância e as condições do cabo influenciam na seção necessária.','Confira o que foi calculado, as hipóteses adotadas e as verificações que ainda faltam.'][step]}</p>`;}
function stepView(step){const c=state.draft;const method=methodOf(c);const groupCount=+c.groupCount;const tempKeys=Object.keys(DB.temperature[method==='D'?'soil':'air'][c.insulation==='PVC'?'PVC':'EPR_XLPE']).sort((a,b)=>+a-+b);
if(step===1)return `${intro(1)}${selectCards(types,c.type,'type')}<div class="fieldset"><div class="input-grid two">${field('Nome do circuito','description',{type:'text',hint:'Ex.: TR-01, Iluminação sala, Motor bomba.'})}${field('Quantidade de equipamentos','quantity',{min:1,step:1,hint:'Quantos equipamentos iguais serão alimentados ao mesmo tempo?'})}</div></div>`;
if(step===2)return `${intro(2)}<div class="input-grid two">${field('Potência de cada equipamento','power',{min:.001,step:'any',tip:true,hint:'Use o valor que aparece na placa.'})}${field('Unidade da potência','unit',{options:[['W','W — watts'],['kW','kW — quilowatts'],['VA','VA — volt-ampères'],['kVA','kVA — quilovolt-ampères'],['CV','CV — cavalos-vapor'],['HP','HP — horsepower']],hint:'Em CV/HP informe também rendimento.'})}${field('Tipo de alimentação','phase',{options:[['mono','Monofásica'],['tri','Trifásica equilibrada']],hint:'Trifásica usa tensão entre fases.'})}${field('Tensão elétrica (V)','voltage',{min:1,step:'any',tip:true,hint:'Ex.: 220 ou 380 V.'})}${field('Fator de potência (cos φ)','powerFactor',{min:.01,max:1,step:.01,tip:true,hint:'Para kVA/VA não é necessário para calcular corrente, mas é usado na estimativa de queda.'})}${['CV','HP'].includes(c.unit)?field('Rendimento do motor (η)','efficiency',{min:.01,max:1,step:.01,tip:true,hint:'Ex.: 0,90 corresponde a 90%.'}):`<div class="field"><label>Corrente de projeto estimada</label><div data-current class="input-like" style="display:flex;align-items:center;background:#f1f6fd;font-weight:750">${fmt(calculate(c).ib)} A</div><span class="hint">Sem correções de temperatura e agrupamento.</span></div>`}</div><div class="notice"><span class="notice-icon">ⓘ</span><span><strong>Potência elétrica ≠ potência mecânica.</strong> Se você informar a potência do eixo em CV/HP, o sistema considera o rendimento. Para kVA, a potência já é aparente.</span></div>`;
if(step===3)return `${intro(3)}${selectCards(installations,c.installation,'installation',true)}<div class="fieldset"><div class="field-title">Detalhes da instalação <span class="badge-note">evitam escolher o método errado</span></div><div class="input-grid ${['surface','tray','overhead'].includes(c.installation)?'two':''}">
${['embedded','conduit'].includes(c.installation)?field('Qual tipo de cabo?','cableForm',{options:[['single','Condutores isolados / cabos unipolares'],['multi','Cabo multipolar']],tip:true,hint:'A1/B1 usam a referência de condutores unipolares; A2/B2, multipolares.'}):''}
${c.installation==='embedded'?field('Material da parede','wall',{options:[['masonry','Alvenaria convencional'],['thermal','Parede termicamente isolante']],hint:'Em alvenaria embutida: B1/B2; em parede termicamente isolante: A1/A2.'}):''}
${field('Material do condutor','metal',{options:[['Cu','Cobre'],['Al','Alumínio']],hint:'As seções e correntes são diferentes.'})}
${field('Isolação do cabo','insulation',{options:[['PVC','PVC — 70 °C'],['EPR','EPR — 90 °C'],['XLPE','XLPE — 90 °C']],tip:true,hint:'Use a especificação real do cabo.'})}</div>
${['tray','overhead'].includes(c.installation)?'<div class="notice warn"><span class="notice-icon">!</span><span>Esta categoria exige definição adicional do método E/F/G ou outro aplicável. O motor atual não contém as respectivas tabelas de capacidade; o resultado da seção permanecerá <b>pendente</b>.</span></div>':c.installation==='buried'?'<div class="notice warn"><span class="notice-icon">!</span><span>O método D da edição de 1997 só será usado como referência inicial. Características do solo, profundidade e agrupamento devem ser conferidos.</span></div>':`<div class="notice"><span class="notice-icon">ⓘ</span><span>Seu método de referência estimado é <b>${esc(method||'a determinar')}</b>, conforme os dados acima. Verifique sua correspondência com a tabela 28 da edição utilizada.</span></div>`}
</div><details class="details"><summary>Não consegui identificar meu método de instalação</summary><div class="details-body"><p class="text-muted">Se as imagens não representam a instalação real, indique isso. Você poderá continuar registrando dados, mas a seleção da seção ficará pendente até que o método seja confirmado.</p><label class="radio-row"><input type="checkbox" data-field="unknownInstallation" ${c.unknownInstallation?'checked':''}>Não sei determinar o método de instalação — deixar análise pendente</label></div></details>`;
if(step===4)return `${intro(4)}<div class="choice-grid"><button data-choose="groupLayout" data-value="bundle" class="choice-btn ${c.groupLayout==='bundle'?'selected':''}"><span class="choice-icon">◉◉◉</span><strong>No mesmo eletroduto ou em feixe</strong><small>Cabos próximos, sem espaçamento relevante. Correspondência possível com a tabela 37, item 1.</small></button><button data-choose="groupLayout" data-value="spaced" class="choice-btn ${c.groupLayout==='spaced'?'selected':''}"><span class="choice-icon">◉ &nbsp; ◉ &nbsp; ◉</span><strong>Separados / espaçados</strong><small>A disposição precisa de uma avaliação específica. Não aplicar automaticamente o item 1.</small></button><button data-choose="groupLayout" data-value="unknown" class="choice-btn ${c.groupLayout==='unknown'?'selected':''}"><span class="choice-icon">?</span><strong>Não sei informar</strong><small>O sistema sinalizará correção pendente quando houver mais de um circuito.</small></button></div><div class="fieldset"><div class="field-title">Quantos circuitos estão agrupados? <button class="help-btn" data-help="groupCount">?</button></div><div class="mini-row">${[1,2,3,4,5,6,8,10].map(n=>`<button class="count-chip ${groupCount===n?'active':''}" type="button" data-choose="groupCount" data-value="${n}">${n}</button>`).join('')}</div><div class="input-grid two compact-form">${field('Outro número de circuitos (1 a 20)','groupCount',{min:1,max:20,step:1,hint:'Circuitos agrupados, não quantidade de condutores individuais.'})}<div class="field"><label>Fator de agrupamento (FCA)</label><div data-group-factor class="input-like" style="display:flex;align-items:center;background:#f3f7fc">${fmt(calculate(c).fca)}</div><span class="hint">Só é determinado para as disposições implementadas.</span></div></div></div>${c.groupCount>1&&c.installation==='buried'?'<div class="notice warn"><span class="notice-icon">!</span><span>Para cabos enterrados agrupados, é preciso consultar fatores específicos de disposição subterrânea. Não será sugerida seção automaticamente.</span></div>':`<div class="notice"><span class="notice-icon">ⓘ</span><span>${groupCount===1?'Com apenas um circuito, não há fator redutor de agrupamento neste modelo.':'O número de circuitos pode reduzir a capacidade de condução de corrente. As condições da tabela devem corresponder à instalação real.'}</span></div>`}`;
if(step===5)return `${intro(5)}<div class="input-grid two">${field('Temperatura no local (°C)','temperature',{options:tempKeys.map(x=>[x,x+' °C']),tip:true,hint:method==='D'?'Temperatura do solo. Condição de referência: 20 °C.':'Temperatura do ambiente ao redor do cabo. Referência: 30 °C.'})}${field('Comprimento até a carga (m)','length',{min:0,step:'any',tip:true,hint:'Distância de ida entre quadro e equipamento.'})}${field('Limite de queda de tensão (%)','maxDrop',{min:.1,max:20,step:.1,tip:true,hint:'Definido pelo critério aplicável ao seu projeto.'})}${field('Condutores carregados','loaded',{options:c.phase==='tri'?[[3,'3 condutores carregados']]:[[2,'2 condutores carregados'],[3,'3 condutores carregados']],tip:true,hint:'Atenção: neutral e harmônicas podem exigir análise.'})}</div>
${method==='D'?`<div class="fieldset"><div class="field-title">Informações adicionais de instalação enterrada</div><div class="input-grid two">${field('Resistividade térmica do solo (K·m/W)','soilResistance',{min:.1,step:.1,tip:true,hint:'Deixe vazio se não souber. Referência histórica da tabela: 2,5.'})}${field('Profundidade estimada (m)','soilDepth',{min:0,step:.1,tip:true,hint:'Parâmetro ainda não aplicado ao cálculo.'})}</div><div class="notice warn"><span class="notice-icon">!</span><span>Os campos são documentais nesta primeira versão; não existe correção automática para resistividade/profundidade diferente da referência.</span></div></div>`:''}
<div class="fieldset"><div class="field-title">Proteção elétrica <span class="badge-note">opcional nesta fase</span></div><div class="input-grid two">${field('Corrente de curto-circuito Ik (kA)','shortIk',{min:0,step:.01,tip:true,hint:'Se for conhecida por cálculo ou estudo.'})}${field('Capacidade de interrupção Icu (kA)','breakerIcu',{min:0,step:.01,tip:true,hint:'Informação do disjuntor real.'})}</div></div><div class="notice warn"><span class="notice-icon">!</span><span>O aplicativo não valida o sistema de proteção inteiro. Mesmo com valores de Ik e Icu, ainda faltam atuação, proteção térmica do cabo, PE, neutro e outras verificações.</span></div>`;
return resultView();}
function resultView(){const r=calculate(state.draft),c=r.c,b=r.chosen;const fact=r.fct!==null&&r.fca!==null?fmt(r.ib/(r.fct*r.fca))+' A':'Pendente';
return `${intro(6)}${r.issues.map(x=>`<div class="notice bad">${esc(x)}</div>`).join('')}<div class="stats-row"><div class="stat"><small>Corrente de projeto (I<sub>B</sub>)</small><strong>${fmt(r.ib)} A</strong></div><div class="stat"><small>Corrente mínima da tabela</small><strong>${fact}</strong></div><div class="stat"><small>Seção preliminar</small><strong>${b?fmt(b.section)+' mm²':'—'}</strong></div></div>
<div class="overview-grid"><div class="key-metric"><small>Seção de cabo calculada</small><strong>${b?fmt(b.section)+' mm²':'Pendente'}</strong><div class="result-note">${esc(c.metal==='Cu'?'Cobre':'Alumínio')} · ${esc(c.insulation)} · método ${esc(r.method||'indefinido')}</div></div><div class="key-metric"><small>Disjuntor nominal preliminar</small><strong>${b?fmt(b.breaker,0)+' A':'Pendente'}</strong><div class="result-note">Curva ${esc(c.breakerCurve)} não validada; I₂/In adotado ${fmt(c.i2Factor)}</div></div></div>
<h3 class="small-heading" style="margin-top:23px">Verificações executadas</h3><div class="checks">${checkLine('Capacidade corrigida do condutor',b?`${fmt(b.iz)} A`:null,b?b.ampOk:null)}${checkLine('Queda de tensão estimada',b?`${fmt(b.dvPct)}% (limite ${fmt(c.maxDrop)}%)`:null,b?b.dropOk:null)}${checkLine('Coordenação de sobrecarga (hipótese I₂)',b?`${fmt(b.breaker)} A`:null,b?Boolean(b.breaker):null)}${checkLine('Ik ≤ Icu (comparação isolada)',r.shortOk===null?null:`${fmt(c.shortIk)} ≤ ${fmt(c.breakerIcu)} kA`,r.shortOk)}${checkLine('Proteção térmica de curto-circuito',null,null)}${checkLine('Neutro, PE, DR/DPS e seccionamento',null,null)}</div>
<div class="result-alert"><strong>Resultado preliminar — não é um projeto aprovado.</strong> As verificações pendentes impedem atestar segurança ou conformidade integral. Utilize a edição normativa apropriada e peça revisão por profissional habilitado para instalações reais.</div>
<details class="details" open><summary>Entenda como os resultados foram obtidos</summary><div class="explain">Corrente calculada a partir da potência e da tensão informadas: <b>${fmt(r.ib)} A</b>.<br> Método de referência: <b>${esc(r.method||'a determinar')}</b> (tabela 28).<br> Capacidade de condução: tabela <b>${r.table}</b>, para <b>${esc(c.insulation)}</b>.<br> Fator de temperatura: <b>${fmt(r.fct)}</b> (tabela 35). Fator de agrupamento: <b>${fmt(r.fca)}</b> (tabela 37 item 1 quando aplicável).<br>${b?`Capacidade da tabela: <b>${fmt(b.itab)} A</b>; após fatores: <b>${fmt(b.iz)} A</b>.<br> Queda de tensão: estimativa usando resistividade do condutor na temperatura-limite da isolação e reatância de ${fmt(state.reactance,3)} Ω/km.`:'A seleção do cabo depende dos dados normativos ainda não resolvidos.'}</div></details>
${r.notices.length?`<h3 class="small-heading" style="margin-top:18px">Pendências e observações</h3>${r.notices.map(x=>`<div class="notice warn"><span class="notice-icon">!</span><span>${esc(x)}</span></div>`).join('')}`:''}
<div class="helper-row"><div class="info-line">Você pode guardar o circuito no projeto mesmo com verificações pendentes.</div><div class="nav-buttons"><button type="button" class="btn primary" id="resultSave">${state.editingId?'Atualizar circuito':'Salvar circuito no projeto'}</button></div></div>`;}
function checkLine(title,value,status){return `<div class="check-row"><span>${title}</span><strong class="${status===true?'text-ok':status===false?'text-bad':'text-pending'}">${value?esc(value)+' · ':''}${status===true?'✓ Verificado parcialmente':status===false?'✕ Não atende':'◷ Pendente'}</strong></div>`;}
function stepper(){return `<ol class="stepper">${LABELS.map((label,i)=>{let step=i+1;return `<li class="${step<state.step?'done':step===state.step?'current':''}"><button type="button" data-step="${step}" aria-label="Ir para etapa ${step}: ${label}" aria-current="${step===state.step?'step':'false'}"><span class="step-dot">${step<state.step?'✓':step}</span><span class="step-name">${label}</span></button></li>`;}).join('')}</ol>`;}
function wizardView(){return `<section class="panel wizard">${stepper()}<div class="step-body">${stepView(state.step)}</div><div class="helper-row"><div class="info-line">${state.step===3?'ⓘ Não conhece o código A1, B1 ou C? Escolha a imagem e confira a explicação.':state.step===6?'ⓘ Os cálculos seguem o escopo histórico declarado, com pendências explícitas.':'ⓘ Suas escolhas ficam salvas localmente neste navegador.'}</div><div class="nav-buttons">${state.step>1?`<button type="button" id="backStep" class="btn secondary">‹ Voltar</button>`:''}${state.step<6?`<button type="button" id="nextStep" class="btn primary">Próximo passo &nbsp;➜</button>`:''}</div></div></section>`;}
function summaryView(){const c=state.draft,r=calculate(c),b=r.chosen;const show=state.step===6||state.mode==='technical'||state.page!=='wizard';const rows=[['▤','Circuito',c.description||'A definir'],['ϟ','Tipo de circuito',types.find(t=>t[0]===c.type)?.[1]||'—'],['▥','Potência total',`${fmt(+c.power*+c.quantity)} ${esc(c.unit)}`],['♧','Tensão',`${fmt(c.voltage)} V (${c.phase==='tri'?'trifásico':'monofásico'})`],['▱','Instalação',c.unknownInstallation?'Não informada':installations.find(x=>x.id===c.installation)?.name||'—'],['▸','Próximo passo',state.step<6?LABELS[state.step]:'Revisar verificações']];return `<section class="panel preview-top"><h2 class="summary-title">Resumo da seleção</h2>${rows.map(([ico,label,value])=>`<div class="summary-item"><div class="left"><span class="glyph">${ico}</span><span>${label}</span></div><strong>${esc(value)}</strong></div>`).join('')}</section><section class="panel preview-result"><h2 class="summary-title">Resultado preliminar <button class="help-btn" data-help="result">?</button></h2><p>${show?'Seleção apenas acadêmica, sujeita às verificações indicadas.':'Os resultados serão exibidos na última etapa, depois de preencher as informações.'}</p>${[['▱','Cabo preliminar',b?`${fmt(b.section)} mm²`:'—'],['▣','Disjuntor nominal',b?`${fmt(b.breaker)} A`:'—'],['ϟ','Queda de tensão',b?`${fmt(b.dvPct)}%`:'—']].map(([ico,label,value])=>`<div class="result-mini ${show&&b?'ready':''}"><div class="rm-icon">${ico}</div><div style="flex:1"><div class="rm-label">${label}</div>${show&&b?`<strong>${value}</strong>`:'<strong>—</strong>'}</div>${show&&b?'':'<span class="pending-label">A definir</span>'}</div>`).join('')}${show?'<p class="result-note">Nenhuma indicação acima significa aprovação do projeto elétrico.</p>':''}</section>`;}
function savedResults(){return state.circuits.map((c,i)=>({i,c,r:calculate(c)}));}
function loadsView(){const rows=savedResults();return `<section class="panel card-section"><div class="card-title"><div><h2>Quadro de cargas</h2><p>Todos os circuitos registrados neste projeto.</p></div><div class="head-actions"><button class="btn secondary small" id="exportJson">⇩ Exportar JSON</button><button class="btn primary small" data-action="new">+ Novo circuito</button></div></div><div class="stats-row"><div class="stat"><small>Circuitos cadastrados</small><strong>${rows.length}</strong></div><div class="stat"><small>Com seção preliminar</small><strong>${rows.filter(x=>x.r.chosen).length}</strong></div><div class="stat"><small>Pendentes ou incompletos</small><strong>${rows.filter(x=>!x.r.chosen).length}</strong></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nº</th><th>Descrição</th><th>Qtd.</th><th>Potência</th><th>Tensão</th><th>Ib (A)</th><th>Método</th><th>Seção</th><th>Proteção</th><th>Estado</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(({i,c,r})=>`<tr><td>${i+1}</td><td><strong>${esc(c.description)}</strong></td><td>${fmt(c.quantity,0)}</td><td>${fmt(c.power)} ${esc(c.unit)}</td><td>${fmt(c.voltage)} V</td><td>${fmt(r.ib)}</td><td>${esc(r.method||'—')}</td><td>${r.chosen?fmt(r.chosen.section)+' mm²':'—'}</td><td>${r.chosen?fmt(r.chosen.breaker)+' A':'—'}</td><td><span class="tag ${r.chosen?'pending':'bad'}">${r.chosen?'Parcial':'Pendente'}</span></td><td><div class="table-actions"><button data-edit="${esc(c.id)}">Editar</button><button data-duplicate="${esc(c.id)}">Duplicar</button><button data-delete="${esc(c.id)}">Excluir</button></div></td></tr>`).join(''):`<tr><td colspan="11" style="text-align:center;padding:36px">Nenhum circuito registrado. Inicie pelo modo guiado.</td></tr>`}</tbody></table></div><div class="notice warn"><span class="notice-icon">!</span><span>“Parcial” significa apenas que foi possível calcular uma combinação preliminar. Ainda existem verificações normativas não realizadas.</span></div></section>`;}
function overviewView(section){const r=calculate(state.draft),b=r.chosen;const titles={sizing:'Dimensionamento',protection:'Dispositivos de proteção',voltage:'Queda de tensão'};let content='';
if(section==='sizing')content=`<div class="overview-grid"><div class="key-metric"><small>Corrente do circuito (Ib)</small><strong>${fmt(r.ib)} A</strong></div><div class="key-metric"><small>Corrente mínima da tabela</small><strong>${r.fct!==null&&r.fca!==null?fmt(r.ib/(r.fct*r.fca))+' A':'—'}</strong></div><div class="key-metric"><small>Cabo preliminar</small><strong>${b?fmt(b.section)+' mm²':'Pendente'}</strong></div><div class="key-metric"><small>Capacidade corrigida Iz</small><strong>${b?fmt(b.iz)+' A':'Pendente'}</strong></div></div><div class="explain">Método ${esc(r.method||'não determinado')} · Tabela ${r.table} · FCT ${fmt(r.fct)} · FCA ${fmt(r.fca)}. Consulta histórica da edição de 1997.</div>${resultView()}`;
if(section==='protection')content=`<div class="overview-grid"><div class="key-metric"><small>Disjuntor nominal preliminar</small><strong>${b?fmt(b.breaker,0)+' A':'Pendente'}</strong></div><div class="key-metric"><small>Corrente de projeto</small><strong>${fmt(r.ib)} A</strong></div></div><div class="explain">Condição considerada: <code>Ib ≤ In ≤ Iz</code> e <code>I₂ ≤ 1,45 × Iz</code>, com I₂/In informado como hipótese. ${b?`Com os valores atuais: ${fmt(r.ib)} A ≤ ${fmt(b.breaker)} A ≤ ${fmt(b.iz)} A.`:'Faltam parâmetros para sugerir uma proteção.'}</div><div class="checks">${checkLine('Sobrecarga (hipótese)',b?`${fmt(b.breaker)} A`:null,b?true:null)}${checkLine('Ik ≤ Icu (comparação)',r.shortOk===null?null:`${fmt(state.draft.shortIk)} ≤ ${fmt(state.draft.breakerIcu)}`,r.shortOk)}${checkLine('Tempo de atuação / energia passante',null,null)}${checkLine('Seletividade e coordenação real',null,null)}</div><div class="result-alert">Curva B/C/D não é definida apenas pela corrente nominal. Verifique tipo, corrente de partida, capacidade de interrupção, curva de atuação e características da instalação.</div>`;
if(section==='voltage')content=`<div class="overview-grid"><div class="key-metric"><small>Queda de tensão estimada</small><strong>${b?fmt(b.dvPct)+'%':'Pendente'}</strong></div><div class="key-metric"><small>Limite informado</small><strong>${fmt(state.draft.maxDrop)}%</strong></div><div class="key-metric"><small>Queda estimada em volts</small><strong>${b?fmt(b.dv)+' V':'Pendente'}</strong></div><div class="key-metric"><small>Comprimento de ida</small><strong>${fmt(state.draft.length)} m</strong></div></div><div class="explain"><code>${state.draft.phase==='tri'?'ΔV ≈ √3 × I × L × (R cosφ + X senφ)':'ΔV ≈ 2 × I × L × (R cosφ + X senφ)'}</code><p>Estimativa com resistência em função da seção e da temperatura-limite da isolação, e reatância ajustável em Configurações. Não substitui características de fabricante nem a análise dos limites reais.</p></div>`;
return `<section class="panel card-section"><div class="card-title"><div><h2>${titles[section]}</h2><p>Valores relativos ao circuito no editor atual: ${esc(state.draft.description)}.</p></div><button class="btn secondary" data-action="wizard">← Voltar ao assistente</button></div>${content}</section>`;}
function techView(){const c=state.draft;return `<section class="panel tech-panel"><h2>Edição técnica do circuito</h2><p class="sub">Todos os parâmetros em uma tela. As alterações são usadas no mesmo motor do modo guiado.</p><div class="technical-grid">${field('Descrição','description',{type:'text'})}${field('Tipo de carga','type',{options:types.map(t=>[t[0],t[1]])})}${field('Quantidade','quantity',{min:1,step:1})}${field('Potência unitária','power',{min:.001,step:'any'})}${field('Unidade','unit',{options:['W','kW','VA','kVA','CV','HP'].map(x=>[x,x])})}${field('Alimentação','phase',{options:[['mono','Monofásico'],['tri','Trifásico']]})}${field('Tensão (V)','voltage',{min:1})}${field('Fator de potência','powerFactor',{min:.01,max:1,step:.01})}${field('Rendimento η','efficiency',{min:.01,max:1,step:.01})}</div><hr><h3 class="small-heading">Condutores e instalação</h3><div class="technical-grid">${field('Ambiente de instalação','installation',{options:installations.map(i=>[i.id,i.name])})}${field('Tipo de cabo','cableForm',{options:[['single','Condutores isolados / unipolares'],['multi','Cabo multipolar']]})}${field('Parede','wall',{options:[['masonry','Alvenaria'],['thermal','Termicamente isolante']]})}${field('Material','metal',{options:[['Cu','Cobre'],['Al','Alumínio']]})}${field('Isolação','insulation',{options:[['PVC','PVC'],['EPR','EPR'],['XLPE','XLPE']]})}${field('Método da tabela 28 (sobrescrever)','methodOverride',{options:[['','Automático'],['A1','A1'],['A2','A2'],['B1','B1'],['B2','B2'],['C','C'],['D','D']],hint:'Selecione somente se souber confirmar na norma.'})}${field('Condutores carregados','loaded',{options:c.phase==='tri'?[[3,'3']]:[[2,'2'],[3,'3']]})}${field('Disposição de agrupamento','groupLayout',{options:[['bundle','Feixe / conduto fechado'],['spaced','Espaçados / outros'],['unknown','Não definida']]})}${field('Nº circuitos agrupados','groupCount',{min:1,max:20,step:1})}${field('Temperatura (°C)','temperature',{min:10,max:80,step:5})}${field('Comprimento de ida (m)','length',{min:0,step:'any'})}${field('ΔV máxima (%)','maxDrop',{min:.1,max:20,step:.1})}</div><hr><h3 class="small-heading">Dispositivo e curto-circuito</h3><div class="technical-grid">${field('Curva do disjuntor','breakerCurve',{options:[['B','B'],['C','C'],['D','D']]})}${field('Relação I₂/In adotada','i2Factor',{min:1,max:3,step:.05,tip:true})}${field('Ik presumida (kA)','shortIk',{min:0,step:.01,tip:true})}${field('Icu do dispositivo (kA)','breakerIcu',{min:0,step:.01,tip:true})}${field('Resistividade solo (K·m/W)','soilResistance',{min:.1,step:.1})}${field('Profundidade de instalação (m)','soilDepth',{min:0,step:.1})}</div><div class="notice warn"><span class="notice-icon">!</span><span>Os parâmetros de curto-circuito e solo podem ser apenas documentais nesta versão. O aplicativo não valida proteção completa nem ajustes para todas as disposições.</span></div><div class="tech-actions"><button class="btn secondary" data-action="guided">Modo guiado</button><button class="btn secondary" data-action="seeResult">Ver resultado</button><button class="btn primary" id="techSave">${state.editingId?'Atualizar circuito':'Salvar circuito no projeto'}</button></div></section>`;}
function referenceView(){const c=state.draft,r=calculate(c);let rows='';let meta='';if(tableShown==='31'||tableShown==='32'){const ins=tableShown==='31'?'PVC':'EPR_XLPE',data=DB.ampacities[ins][c.metal],method=r.method&&DB.meta.columns.includes(`${r.method}/2`)?r.method:'B1',idx2=DB.meta.columns.indexOf(`${method}/2`),idx3=DB.meta.columns.indexOf(`${method}/3`);meta=`Cabo ${ins==='PVC'?'PVC 70 °C':'EPR/XLPE 90 °C'} · ${c.metal==='Cu'?'Cobre':'Alumínio'} · método ${method}`;rows=Object.entries(data).filter(([k])=>+k>=1.5).slice(0,21).map(([k,v])=>`<tr><td>${fmt(+k)}</td><td>${fmt(v[idx2])}</td><td>${fmt(v[idx3])}</td></tr>`).join('');}else if(tableShown==='35'){const kind=c.insulation==='PVC'?'PVC':'EPR_XLPE',mode=r.method==='D'?'soil':'air',pv=DB.temperature[mode].PVC,ev=DB.temperature[mode].EPR_XLPE;meta='Fatores de correção por temperatura, valores de referência da edição 1997';rows=Object.keys(ev).map(k=>`<tr><td>${k} °C</td><td>${pv[k]??'—'}</td><td>${ev[k]}</td></tr>`).join('');}else if(tableShown==='37'){meta='Tabela 37, apenas item 1: feixes / cabos em condutos fechados';rows=Object.entries(DB.group1).map(([k,v])=>`<tr><td>${k}</td><td>${fmt(v)}</td><td>Item 1</td></tr>`).join('');}
return `<section class="panel card-section reference-table"><div class="card-title"><div><h2>Tabela ${esc(tableShown)} · consulta normativa</h2><p>${esc(meta||'Tabela 28: referências dos métodos de instalação (edição 1997).')}</p></div><button class="btn secondary" data-action="wizard">Voltar</button></div>${tableShown==='28'?`<div class="explain"><p><b>A1/A2:</b> em eletroduto de parede termicamente isolante; A1 para condutores isolados/cabos unipolares, A2 para cabo multipolar.</p><p><b>B1/B2:</b> em eletroduto aparente ou embutido em alvenaria, conforme condição prevista; B1 para condutores isolados/unipolares e B2 para multipolares.</p><p><b>C:</b> cabos aplicáveis diretamente em parede; <b>D:</b> instalação enterrada conforme referência.</p><p>O enquadramento exato exige a tabela 28 e a instalação real.</p></div>`:`<div class="table-wrap"><table class="data-table"><thead><tr><th>${tableShown==='35'?'Temperatura':tableShown==='37'?'Circuitos':'Seção (mm²)'}</th><th>${tableShown==='35'?'PVC':tableShown==='37'?'Fator FCA':'2 carregados (A)'}</th><th>${tableShown==='35'?'EPR/XLPE':tableShown==='37'?'Condição':'3 carregados (A)'}</th></tr></thead><tbody>${rows}</tbody></table></div>`}<div class="notice warn"><span class="notice-icon">!</span><span>Consulta parcial de dados da NBR 5410:1997 fornecida. Não contém todas as notas, exceções e condições da norma; não usar como substituto da publicação normativa.</span></div></section>`;}
async function render(){const version=++renderVersion,snapshot=viewKey();await prepareResults([state.draft,...state.circuits]);if(version!==renderVersion||snapshot!==viewKey())return;if(!DB){$('mainPanel').innerHTML='<div class="notice bad">Erro: dados das tabelas não foram carregados.</div>';return;}$('projectName').value=state.projectName;
const mode=state.mode==='guided',isWizard=state.page==='wizard';$('guidedMode').classList.toggle('active',mode);$('technicalMode').classList.toggle('active',!mode);$('guidedMode').setAttribute('aria-pressed',String(mode));$('technicalMode').setAttribute('aria-pressed',String(!mode));$('pageTitle').textContent=state.page==='loads'?'Quadro de cargas':state.page==='reference'?'Tabelas da NBR 5410':state.page==='wizard'?'Dimensionamento de Circuito':{sizing:'Dimensionamento',protection:'Dispositivos de proteção',voltage:'Queda de tensão'}[state.page]||'VoltCalc';$('pageSubtitle').textContent=state.page==='wizard'?'Siga o passo a passo para dimensionar o circuito de forma simples e transparente.':'Dados de referência, cálculos preliminares e verificações disponíveis.';
document.querySelectorAll('.nav-item[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===state.page||state.page==='reference'&&e.dataset.page==='wizard'));
$('mainPanel').innerHTML=isWizard?(mode?wizardView():techView()):state.page==='loads'?loadsView():state.page==='reference'?referenceView():overviewView(state.page);
renderSummary();}
async function renderSummary(){const version=++summaryVersion,key=resultKey(state.draft);await prepareResults([state.draft]);if(version!==summaryVersion||key!==resultKey(state.draft))return;$('summaryPanel').innerHTML=summaryView();const r=calculate(state.draft);document.querySelectorAll('[data-current]').forEach(el=>el.textContent=fmt(r.ib)+' A');document.querySelectorAll('[data-group-factor]').forEach(el=>el.textContent=fmt(r.fca));const status=$('connectionStatus');if(status){status.hidden=!serviceError;status.textContent=serviceError;}}
function setField(key,value){const c=state.draft;if(!Object.prototype.hasOwnProperty.call(c,key))return;if(['quantity','power','voltage','powerFactor','efficiency','loaded','groupCount','temperature','length','maxDrop','i2Factor','shortIk','breakerIcu','soilResistance','soilDepth'].includes(key))c[key]=value;
else if(key==='unknownInstallation')c[key]=Boolean(value);else c[key]=String(value);
if(key==='phase')c.loaded=value==='tri'?3:2;
if(key==='methodOverride'&&value)c.unknownInstallation=false;
if(key==='installation'){c.methodOverride='';c.unknownInstallation=false;if(value==='buried'&&!(String(c.temperature) in DB.temperature.soil[c.insulation==='PVC'?'PVC':'EPR_XLPE']))c.temperature=20;}
if(key==='type'){if(value==='motor'&&['kVA','VA'].includes(c.unit)){c.unit='kW';c.power=5.5;c.powerFactor=.85;}if(value==='lighting'){c.unit='W';c.power=100;}if(value==='shower'){c.unit='W';c.power=5500;c.powerFactor=1;}}
if(key==='insulation'){let t=DB.temperature[methodOf(c)==='D'?'soil':'air'][value==='PVC'?'PVC':'EPR_XLPE'];if(!(String(c.temperature) in t))c.temperature=methodOf(c)==='D'?20:30;}
persist();}
function chooseValue(key,value){setField(key,value);render();}
function saveCircuit(){for(let i=1;i<=5;i++)if(markIssue(state.draft,i)){state.step=i;state.mode='guided';state.page='wizard';render();toast('Complete as informações da etapa '+i+'.');return;}
const c=clean({...state.draft,id:state.editingId||id()});if(state.editingId){const i=state.circuits.findIndex(x=>x.id===state.editingId);if(i>=0)state.circuits[i]=c;else state.circuits.push(c);toast('Circuito atualizado no projeto.');}else {if(state.circuits.length>=300){toast('Limite de 300 circuitos atingido.');return;}state.circuits.push(c);toast('Circuito adicionado ao projeto.');}
state.selected=c.id;state.editingId=null;state.draft=clean({...c,id:id()});const stored=persist();state.page='loads';render();if(!stored)toast('Circuito em memória; falha ao salvar. Exporte um backup JSON.');}
function editCircuit(cid){const c=state.circuits.find(x=>x.id===cid);if(!c)return;state.draft=clean(c);state.editingId=cid;state.selected=cid;state.page='wizard';state.step=1;state.mode='guided';persist();render();window.scrollTo({top:0,behavior:'smooth'});}
function deleteCircuit(cid){const c=state.circuits.find(x=>x.id===cid);if(!c)return;if(!confirm(`Excluir o circuito "${c.description}"?`))return;state.circuits=state.circuits.filter(x=>x.id!==cid);if(state.selected===cid)state.selected=state.circuits[0]?.id||null;persist();render();toast('Circuito excluído.');}
function duplicateCircuit(cid){const c=state.circuits.find(x=>x.id===cid);if(!c)return;if(state.circuits.length>=300){toast('Limite atingido.');return;}let copy=clean({...c,id:id(),description:(c.description+' - cópia').slice(0,70)});state.circuits.push(copy);state.selected=copy.id;persist();render();toast('Circuito duplicado.');}
function route(page){state.page=page;render();window.scrollTo({top:0,behavior:'smooth'});}
function modal(title,body,buttons='<button class="btn secondary" data-modal-close>Fechar</button>'){$('modalRoot').innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${body}<div class="modal-foot">${buttons}</div></div>`;$('modalRoot').hidden=false;}
function closeModal(){$('modalRoot').hidden=true;$('modalRoot').innerHTML='';}
function settingsModal(){modal('Configurações do VoltCalc',`<p>O projeto fica salvo neste navegador. Faça backup JSON para transferir entre computadores.</p><div class="field"><label>Reatância presumida para queda de tensão (Ω/km)</label><input id="reactanceInput" type="number" min="0" max="2" step=".01" value="${esc(state.reactance)}"><span class="hint">É apenas uma estimativa configurável; confirme com os dados reais do cabo.</span></div><div class="divider"></div><div class="field-title">Arquivo do projeto</div><div class="field-row"><button class="btn secondary" id="exportSettings">Exportar backup JSON</button><button class="btn secondary" id="importSettings">Importar backup JSON</button><input type="file" id="importFile" accept=".json,application/json" hidden></div><div class="notice warn">Referência histórica: NBR 5410:1997. Esta versão não cobre todo o dimensionamento normativo.</div>`, `<button class="btn secondary" data-modal-close>Cancelar</button><button class="btn primary" id="saveSettings">Salvar ajustes</button>`);}
function exportJson(){const raw=JSON.stringify({format:'VoltCalcGuiado-v2',projectName:state.projectName,circuits:state.circuits,reactance:state.reactance,reference:'NBR5410:1997'},null,2);const href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download='VoltCalc_'+state.projectName.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/gi,'_').slice(0,45)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),500);toast('Backup do projeto exportado.');}
async function importJson(file){if(!file)return;if(file.size>4e6){toast('Arquivo maior que 4 MB.');return;}try{const data=JSON.parse(await file.text());if(!Array.isArray(data.circuits)||data.circuits.length>300)throw Error('Arquivo inválido ou acima de 300 circuitos');if(data.format!=='VoltCalcGuiado-v2')throw Error('Formato de backup não reconhecido');const reactance=data.reactance===undefined?.08:num(data.reactance);if(!Number.isFinite(reactance)||reactance<0||reactance>2)throw Error('Reatância inválida no backup');if(!confirm(`Importar ${data.circuits.length} circuitos e substituir os atuais?`))return;state.reactance=reactance;state.circuits=data.circuits.map(clean);state.projectName=String(data.projectName||'Projeto importado').slice(0,60);state.selected=state.circuits[0]?.id||null;state.editingId=null;state.draft=clean(state.circuits[0]||newCircuit());persist();closeModal();route('loads');toast('Projeto importado.');}catch(e){toast('Importação recusada: '+e.message);}}
async function report(){const snapshot=viewKey();if(!await prepareResults(state.circuits)){toast(serviceError);return;}if(snapshot!==viewKey()){toast('Os dados mudaram. Exporte o relatório novamente.');return;}let items=savedResults(),tab=items.map(({i,c,r})=>`<tr><td>${i+1}</td><td>${esc(c.description)}</td><td>${fmt(c.quantity,0)}</td><td>${fmt(c.power)} ${esc(c.unit)}</td><td>${fmt(c.voltage)}</td><td>${fmt(r.ib)} A</td><td>${esc(r.method||'—')}</td><td>${r.chosen?fmt(r.chosen.section)+' mm²':'Pendente'}</td><td>${r.chosen?fmt(r.chosen.breaker)+' A':'Pendente'}</td><td>${r.chosen?'Parcial':'Pendente'}</td></tr>`).join('');$('printArea').innerHTML=`<h1>VoltCalc — Memorial preliminar</h1><p><b>Projeto:</b> ${esc(state.projectName)}<br><b>Data:</b> ${new Date().toLocaleDateString('pt-BR')}<br><b>Referência didática:</b> NBR 5410:1997, edição histórica fornecida</p><div class="report-warning"><strong>AVISO:</strong> documento de estudo. Não comprova conformidade com a edição normativa vigente nem segurança de uma instalação real. Os cálculos são parciais.</div><h2>Quadro de circuitos</h2><table><thead><tr><th>Nº</th><th>Descrição</th><th>Qtd.</th><th>Potência</th><th>Tensão</th><th>Ib</th><th>Método</th><th>Seção</th><th>Disjuntor</th><th>Status</th></tr></thead><tbody>${tab||'<tr><td colspan="10">Nenhum circuito registrado.</td></tr>'}</tbody></table><h2>Observações e limites</h2><p>Referências: tabela 28 (métodos), tabelas 31 e 32 (capacidade de corrente para A1 a D), tabela 35 (temperatura) e tabela 37 item 1 (agrupamento). Para bandejas e leitos E/F/G e disposições especiais, a seleção é indicada como pendente. Estimativas de queda de tensão usam reatância simplificada. A seleção preliminar da proteção não verifica a atuação real, energia passante, proteção térmica contra curto-circuito, neutro, PE, DR, DPS nem seccionamento automático. Cabos enterrados exigem validação de resistividade, profundidade e agrupamento. Os campos de proteções não substituem ensaios/cálculos por profissional habilitado.</p><p>Software acadêmico: conferir edição vigente da norma e dados de fabricantes antes de qualquer utilização em obra.</p>`;window.print();}
function clickHandler(ev){const btn=ev.target.closest('button');if(!btn)return;
if(btn.dataset.page){route(btn.dataset.page);return;}
if(btn.dataset.step){let next=+btn.dataset.step;if(next>state.step){for(let i=state.step;i<next;i++)if(!checkStep(state.draft,i))return;}state.step=next;render();return;}
if(btn.dataset.choose){chooseValue(btn.dataset.choose,btn.dataset.value);return;}
if(btn.dataset.help){const key=btn.dataset.help;modal(key==='result'?'Sobre os resultados':'Ajuda para preencher',`<p>${esc(helps[key]||'Os resultados são parciais e dependem das condições reais da instalação. Verificações completas precisam de dados adicionais e consulta à norma aplicável.')}</p>`);return;}
if(btn.dataset.table){tableShown=btn.dataset.table;route('reference');return;}
if(btn.dataset.edit){editCircuit(btn.dataset.edit);return;}
if(btn.dataset.duplicate){duplicateCircuit(btn.dataset.duplicate);return;}
if(btn.dataset.delete){deleteCircuit(btn.dataset.delete);return;}
if(btn.dataset.action==='new'){state.draft=newCircuit();state.draft.description='';state.editingId=null;state.step=1;state.mode='guided';route('wizard');return;}
if(btn.dataset.action==='wizard'||btn.dataset.action==='guided'){state.mode='guided';route('wizard');return;}
if(btn.dataset.action==='seeResult'){state.mode='guided';state.step=6;route('wizard');return;}
if(btn.dataset.modalClose!==undefined||btn.hasAttribute('data-modal-close')){closeModal();return;}
switch(btn.id){case 'backStep':state.step=Math.max(1,state.step-1);render();break;case 'nextStep':if(checkStep(state.draft,state.step)){state.step=Math.min(6,state.step+1);render();}break;case 'resultSave':case 'techSave':saveCircuit();break;case 'guidedMode':state.mode='guided';state.page='wizard';render();break;case 'technicalMode':state.mode='technical';state.page='wizard';render();break;case 'saveBtn':state.projectName=$('projectName').value||'Projeto';if(persist())toast('Projeto salvo neste navegador.');else toast('Não foi possível salvar neste navegador.');break;case 'printBtn':case 'sidebarReport':report();break;case 'sidebarSettings':case 'settingsBtn':settingsModal();break;case 'saveSettings':{let value=num($('reactanceInput')?.value);if(!Number.isFinite(value)||value<0||value>2){toast('Reatância precisa estar entre 0 e 2 Ω/km.');return;}state.reactance=value;persist();closeModal();render();toast('Configurações salvas.');break;}case 'exportJson':case 'exportSettings':exportJson();break;case 'importSettings':$('importFile').click();break;}}
function changeHandler(ev){let field=ev.target?.dataset?.field;if(!field)return;const target=ev.target;const val=target.type==='checkbox'?target.checked:target.value;setField(field,val);if(target.tagName==='SELECT'||target.type==='checkbox')render();else renderSummary();}
function inputHandler(ev){const f=ev.target?.dataset?.field;if(!f)return;if(ev.target.tagName==='SELECT')return;setField(f,ev.target.type==='checkbox'?ev.target.checked:ev.target.value);renderSummary();}
load();render();document.addEventListener('click',clickHandler);document.addEventListener('change',changeHandler);document.addEventListener('input',inputHandler);document.addEventListener('change',ev=>{if(ev.target.id==='importFile')importJson(ev.target.files?.[0]);if(ev.target.id==='projectName'){state.projectName=String(ev.target.value||'Projeto').slice(0,60);persist();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('modalRoot').hidden)closeModal();});$('modalRoot').addEventListener('click',e=>{if(e.target===$('modalRoot'))closeModal();});
})();
